import{_ as p}from"./chunks/image-002.Dp2-bnLm.js";import{_ as t,o as l,c as o,a3 as n}from"./chunks/framework.DdpBa4_E.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/yan-tie-lun/73-大论第五十九.md","filePath":"books/yan-tie-lun/73-大论第五十九.md","lastUpdated":1794316978000}'),i={name:"books/yan-tie-lun/73-大论第五十九.md"};function _(e,a,s,r,c,d){return l(),o("div",null,[...a[0]||(a[0]=[n('<p>大论第五十九 【题解】</p><p>本篇题为“大论”，有“总论”之意，双方辩论以礼治国还是以法治国的问题。大夫认为，时世不同，治国方法就要随之而变，不能以虞、夏、商、周的方法来治理当世。文学则认为，民众本性并没有根本改变，变化的是风俗，因此治国要从移风易俗入手，用仁义教化来培养良风善俗，做到防患于未然，这才是治国的根本。辩论到最后，大夫图穷匕首见，将攻击矛头直指儒家祖师孔子，认为孔子具备了强、贪、愚、耻四项恶劣品质。文学则坚决捍卫孔子形象，热烈赞扬孔子拯救乱世的高尚情怀。辩论以双方各执己见而解散。</p><p>大夫曰：“呻吟槁简[(1)]，诵死人之语，则有司不以文学[(2)]。文学知狱之在廷后而不知其事[(3)]，闻其事而不知其务。夫治民者，若大匠之斫[(4)]，斧斤而行之，中绳则止[(5)]。杜大夫、王中尉之等[(6)]，绳之以法，断之以刑，然后寇止奸禁。故射者因槷[(7)]，治者因法。虞、夏以文[(8)]，殷、周以武[(9)]，异时各有所施。今欲以敦朴之时，治抏弊之民[(10)]，是犹迁延而拯溺[(11)]，揖让而救火也[(12)]。”</p><p>【注释】</p><p>[(1)]槁简：干枯的竹简。</p><p>[(2)]以：通“似”，如。</p><p>[(3)]廷后：朝廷后面。</p><p>[(4)]斫（zhuó）：砍削。</p><p>[(5)]中（zhònɡ）绳：符合绳墨。绳，木工取直的墨线。</p><p>[(6)]杜大夫：御史大夫杜周。王中尉：中尉王温舒。</p><p>[(7)]槷（niè）：借为“臬”，箭靶。原作“势”，据陈遵默说校改。</p><p>[(8)]虞、夏以文：虞、夏是以禅让方式实现权力交接。</p><p>[(9)]殷、周以武：商汤、周武王是以武力夺取政权。</p><p>[(10)]抏（wán）弊：巧诈，狡诈。</p><p>[(11)]迁延：拖延时间，慢腾腾。拯溺：拯救落水者。</p><p>[(12)]揖让：拱手谦让。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“吟唱干枯的竹简，诵读死人的语句，主管官员不像文学。文学只知道监狱在朝廷之后，但并不知狱中事情，即使是听说一些牢狱事情，也不知如何处理。治理民众，如同木匠砍削，挥动斧斤，符合绳墨就停止。杜周大夫、王温舒中尉等人，将罪人绳之以法，判刑定罪，然后盗寇止息，奸邪禁止。因此射手要根据箭靶射箭，治国者要根据法令。虞、夏运用文治方法，殷、周则以武力夺取政权，时世不同，所用治国方法也就不一样。如今想用敦朴时代的文教，来治理狡诈的民众，这就如同拖延时间去拯救落水者，打躬作揖去救火一样。”</p><p>文学曰：“文王兴而民好善[(1)]，幽、厉兴而民好暴[(2)]，非性之殊，风俗使然也。故商、周之所以昌，桀、纣之所以亡也，汤、武非得伯夷之民以治，桀、纣非得跖、蹻之民以乱也，故治乱不在于民。孔子曰：‘听讼吾犹人也，必也使无讼乎！’[(3)]无讼者难[(4)]，讼而听之易。夫不治其本而事其末[(5)]，古之所谓愚，今之所谓智。以棰楚正乱[(6)]，以刀笔正文[(7)]，古之所谓贼，今之所谓贤也。”</p><p>【注释】</p><p>[(1)]兴：兴起。</p><p>[(2)]幽、厉：周幽王、周厉王，他们是西周末年两个昏君。</p><p>[(3)]听讼吾犹人也，必也使无讼乎：见于《论语·颜渊》。听讼，断案。必，一定。无讼，没有诉讼案件。</p><p>[(4)]无讼者难：“无”字原无，据王利器说校补。</p><p>[(5)]本：仁义。末：刑罚。</p><p>[(6)]棰楚：棰杖、荆条。</p><p>[(7)]刀笔：用刀笔书写判词，此处指刑罚。刀，用来削去竹简上错误的字。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“文王兴起而民众爱好行善，周幽王、周厉王兴起而民众爱好横暴，这不是民众性格发生变化，而是社会风俗使他们变成这样。因此商、周之所以昌盛，夏桀、殷纣王之所以灭亡，并不是商汤、周武王得到伯夷这样的民众才得到治理，也不是夏桀、殷纣王得到跖、蹻这样的民众才导致大乱，所以治和乱不取决于民众。《论语·颜渊》载孔子说：‘对于断案，我与其他人一样。一定要使诉讼的事件完全消灭才好！’没有诉讼很难做到，有诉讼而去断案是容易的事。不治理根本而从事末端，这就是古代人所说的愚，今天人所说的智。用棰杖荆条来纠正混乱，用法吏刀笔判词来纠正文治，这就是古代人所说的贼，今天人所说的贤。”</p><p>大夫曰：“俗非唐、虞之时，而世非许由之民[(1)]，而欲废法以治，是犹不用隐括斧斤[(2)]，欲挠曲直枉也[(3)]。故为治者不待自善之民，为轮者不待自曲之木。往者，应少、伯正之属溃梁、楚[(4)]，昆卢、徐谷之徒乱齐、赵[(5)]，山东、关内暴徒，保人阻险[(6)]。当此之时，不任斤斧[(7)]，折之以武[(8)]，而乃始设礼修文，有似穷医[(9)]，欲以短针而攻疽[(10)]，孔丘以礼说跖也[(11)]。”</p><p>【注释】</p><p>[(1)]许由：传说中的上古隐士。《史记·伯夷列传》载：“说者曰，尧让天下于许由，许由不受，耻之，逃隐。”</p><p>[(2)]隐括：纠正曲木的工具。斧斤：斧头。</p><p>[(3)]挠曲：将直的弄弯曲。直枉：把弯曲的东西弄直。</p><p>[(4)]应少：《史记·酷吏列传》作“杜少”。伯正：《史记·酷吏列传》作“伯政”。溃：击溃。</p><p>[(5)]昆卢：《史记·酷吏列传》作“坚卢”。徐谷：《史记·酷吏列传》作“徐勃”。</p><p>[(6)]保人阻险：聚众恃险。保，通“堡”，聚集。阻，恃。</p><p>[(7)]斤斧：比喻刑罚。</p><p>[(8)]折之以武：以武力折服他们。</p><p>[(9)]穷医：无能的医生。</p><p>[(10)]攻疽（jū）：治疗毒疮。</p><p>[(11)]孔丘以礼说跖：《庄子·盗跖》中的寓言，孔子本想以礼义劝说盗跖，结果大败而归。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“现在风俗不是唐尧、虞舜时期的风俗，世上民众也不是许由那样的民众，你们却想废除法律来治民，这就如同不用纠正曲木的工具和斧斤，却想把直的东西弄弯曲、把弯曲的东西弄直一样。因此治国的人不必等待自然善良的民众，制作车轮的工匠不必等待自然弯曲的树木。以前，应少、伯正等人击溃梁、楚官军，昆卢、徐谷等人扰乱齐、赵，关外和关内的暴徒，聚众恃险。在那个时候，不用刑罚，不用武力折服他们，而去设礼节，修文治，这就如同无能的医生，想以短针治疗毒疮，如同孔丘用礼义游说盗跖一样。”</p><p>文学曰：“残材木以成室屋者[(1)]，非良匠也。残贼民人而欲治者，非良吏也。故公输子因木之宜[(2)]，圣人不费民之性[(3)]。是以斧斤简用，刑罚不任，政立而化成。扁鹊攻于凑理[(4)]，绝邪气，故痈疽不得成形。圣人从事于未然，故乱原无由生[(5)]。是以砭石藏而不施[(6)]，法令设而不用。断已然[(7)]，凿已发者[(8)]，凡人也。治未形，睹未萌者，君子也。”</p><p>【注释】</p><p>[(1)]残：糟蹋，破坏。成：建成。</p><p>[(2)]公输子：即鲁班。</p><p>[(3)]费：通“拂”，违背。</p><p>[(4)]扁鹊：战国名医。凑理：经络脉理。凑，通“腠”。</p><p>[(5)]原：同“源”。</p><p>[(6)]砭（biān）石：古代治病用的石针。</p><p>[(7)]断已然：给已经发生的案件断案。</p><p>[(8)]凿已发：处理已经发生的事件。凿，凿除。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“糟蹋木材来构建房屋，不算好木匠。残害民众来进行治理，不能算好官。因此鲁班顺应木材所宜，圣人不违背民众天性。所以好木匠少用斧头，好官不用刑罚，政教确立后教化便形成。扁鹊治疗病人经络腠理，断绝致病的邪气，因而毒疮不能形成。圣人在事件未发生之前进行教化，因而动乱根源无由产生。所以治病的砭石收藏起来而不用，法令设置而不用施行。诊断已经明显的病情，处理已经发生的事件，这是平凡的人。治闻未成形的病，看到未发生的事，这是君子。”</p><p>大夫曰：“文学所称圣知者[(1)]，孔子也，治鲁不遂[(2)]，见逐于齐[(3)]，不用于卫[(4)]，遇围于匡[(5)]，困于陈、蔡[(6)]。夫知时不用犹说，强也[(7)]；知困而不能已[(8)]，贪也；不知见欺而往[(9)]，愚也；困辱不能死，耻也。若此四者[(10)]，庸民之所不为也，而况君子乎！商君以景监见[(11)]，应侯以王稽进[(12)]。故士因士[(13)]，女因媒。至其亲显[(14)]，非媒士之力。孔子不以因进见而能往者[(15)]，非贤士才女也。”</p><p>【注释】</p><p>[(1)]知：同“智”。</p><p>[(2)]遂：成功。据《史记·孔子世家》记载，齐国送女乐给季桓子，季桓子三日不听政。鲁国郊祭，不赠送祭肉给大夫。孔子因此愤而离开鲁国。</p><p>[(3)]见逐于齐：孔子适齐，齐景公欲以尼谿田封孔子，受到齐相晏婴的阻挠。其后齐大夫欲害孔子，孔子去齐返鲁。按，孔子适齐在前，孔子去鲁在后。</p><p>[(4)]不用于卫：孔子在周游列国的十四年中，曾数次出入卫国，均未得到卫君重用。</p><p>[(5)]遇围于匡：孔子由于长相似阳虎，阳虎曾对匡人施暴，因此孔子在自卫至陈、路过匡地时，被匡人误以为是阳虎而将孔子包围。</p><p>[(6)]困于陈、蔡：楚国使人聘孔子，陈蔡害怕孔子在楚国受到重用而对自己不利，因此派兵将孔子困于野地。</p><p>[(7)]知时不用犹说：孔子知道自己不为时人所用，还要游说诸侯。强：顽固，固执。</p><p>[(8)]已：停止，罢休。</p><p>[(9)]见欺：被欺骗。</p><p>[(10)]四者：强、贪、愚、耻。</p><p>[(11)]商君以景监见：商鞅游说秦孝公之前，通过孝公宠臣景监引荐。景监，战国时期秦孝公的宦官。</p><p>[(12)]应侯：范雎。王稽：秦昭王侍者。范雎为魏国大夫须贾舍人，因被疑与齐国私通受笞近死。后更名张禄，通过郑安平结识秦国使者王稽，入秦后拜相，封为应侯。</p><p>[(13)]因：依靠。</p><p>[(14)]亲：得到君主亲近。显：显达。</p><p>[(15)]孔子不以因进见而能往者：此句原作“孔子曰进见而不以能往者”，据王利器说校改。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“文学所称道的圣人和智者，就是孔子。孔子治理鲁国不成功，被齐国驱逐，在卫国得不到任用，在匡地遭到包围，在陈、蔡野地被围困。孔子明知自己不为时人所用，还要游说诸侯，这是固执；知道自己处境困窘而不肯罢休，这是贪婪；不知道自己会被欺骗而前往，这是愚蠢；受到围困之辱而不能死节，这是耻辱。像固执、贪婪、愚蠢、耻辱四者，连平庸的民众也不会去做，何况君子呢！商君是通过景监引荐而见到秦孝公，应侯范雎是通过王稽而得到进用。因此士要靠士的引荐，女子要靠媒人介绍。至于能不能亲近君主飞黄腾达，那就不是媒人或士人的力量了。孔子不是通过他人引荐去进见诸侯，他却自己周游列国，这说明孔子不是贤士才女那样的人啊。”</p><p>文学曰：“孔子生于乱世，思尧、舜之道，东西南北，灼头濡足[(1)]，庶几世主之悟[(2)]。悠悠者皆是[(3)]，君闇[(4)]，大夫妒，孰合有媒[(5)]？是以嫫母饰姿而矜夸[(6)]，西子彷徨而无家[(7)]。非不知穷厄而不见用[(8)]，悼痛天下之祸[(9)]，犹慈母之伏死子也，知其不可如何，然恶已[(10)]。故适齐，景公欺之，适卫，灵公围[(11)]，阳虎谤之[(12)]，桓魋害之[(13)]。夫欺害圣人者，愚惑也；伤毁圣人者，狂狡也[(14)]。狡惑之人[(15)]，非人也。夫何耻之有！孟子曰：‘观近臣者以所为主，观远臣者以其所主。’[(16)]使圣人伪容苟合[(17)]，不论行择友[(18)]，则何以为孔子也！”</p><p>【注释】</p><p>[(1)]灼头濡（rú）足：烧了头，湿了脚。</p><p>[(2)]庶几：差不多，表示希望、可能的副词。</p><p>[(3)]悠悠：众多的样子。</p><p>[(4)]闇：同“暗”，昏聩。</p><p>[(5)]合：与。</p><p>[(6)]嫫母：丑女。矜夸：炫耀自夸。</p><p>[(7)]西子：西施。彷徨：徘徊。</p><p>[(8)]穷厄：困窘。</p><p>[(9)]悼痛：哀伤悲痛。</p><p>[(10)]恶：通“乌”，哪里。已：止。</p><p>[(11)]灵公围：卫灵公没有围攻孔子，这是文学夸张说法。</p><p>[(12)]阳虎谤之：《论语·阳货》载：“阳货欲见孔子，孔子不见，归孔子豚。孔子时其亡也，而往拜之。遇诸途。谓孔子曰：‘来！予与尔言。’曰：‘怀其宝而迷其邦，可谓仁乎？’曰：‘不可！好从事而亟失时，可谓知乎？’曰：‘不可！日月逝矣，岁不我与。’孔子曰：‘诺，吾将仕矣。’”此为文学所本。阳虎，鲁国大夫季孙氏的家臣，季孙氏专鲁国之政，阳虎又专季孙氏之政，被孔子称之为“陪臣执国命”。</p><p>[(13)]桓魋（tuí）害之：《史记·孔子世家》：“孔子去曹适宋，与弟子习礼大树下。宋司马桓魋欲杀孔子，拔其树。孔子去。弟子曰：‘可以速矣。’孔子曰：‘天生德于予，桓魋其如予何！’”</p><p>[(14)]狂狡：疯狂狡诈的人。</p><p>[(15)]狡惑之人：“惑”上原无“狡”字，据王利器说校补。</p><p>[(16)]观近臣者以所为主，观远臣者以其所主：见于《孟子·万章上》。所为主，所接待的客人。其所主，所寄居的主人。</p><p>[(17)]伪容苟合：伪装欢容，曲意迎合。</p><p>[(18)]论行择友：根据品行选择朋友。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“孔子生在乱世，思慕尧、舜之道，东西南北，头顶如火骄阳，足踏泥泞污水，希望诸侯醒悟。天下普遍的情形是，君主昏暗，大夫嫉妒，谁给孔子做介绍人呢？因此丑女嫫母修饰姿容而矜持自夸，美女西施徘徊而无婆家。孔子并不是不知道自身处境困窘而不被诸侯所用，而是伤痛天下乱祸，就像慈母伏在死去的儿子身上一样，他知道不可能有所作为，但他哪里能够停止救世呢？因此他到了齐国，齐景公欺骗他；到了卫国，卫灵公派人围攻他；阳虎批评他，桓魋危害他。欺骗危害圣人的人，是愚蠢困惑；伤害诋毁圣人的人，是疯狂狡诈。狡诈狂惑的人，不是真正的人。他们哪里有什么羞耻感！孟子说：‘观察君主近臣，要看他所接待的人，观察君主的远方之臣，要看他所寄居的主人。’假使圣人伪装欢容曲意迎合，不根据品行选择朋友，那么怎么能成为孔子呢！”</p><p>大夫抚然内惭[(1)]，四据而不言[(2)]。</p><p>当此之时，顺风承意之士如编[(3)]，口张而不歙[(4)]，舌举而不下[(5)]，暗然而怀重负而见责[(6)]。</p><p>大夫曰：“诺，胶车倏逢雨[(7)]，请与诸生解[(8)]。”</p><p>【注释】</p><p>[(1)]抚然：失望的样子。抚，通“怃”。</p><p>[(2)]四据：四肢疲乏。古人席地跪坐，臀部放在足跟之上，两手离席很近，疲乏时以两手触地。</p><p>[(3)]顺风承意之士：指丞相史和御史。编：编成一排，即依次列坐。</p><p>[(4)]歙（xī）：通“噏”，合。</p><p>[(5)]舌举：原作“举舌”，据王利器说校改。</p><p>[(6)]暗然：通“黯然”。</p><p>[(7)]胶车倏（shū）风雨：车子用胶粘合，遇到雨水后会散开。这是古代歇后语，意为四散。倏，突然。原作“修”，据张敦仁说校改。</p><p>[(8)]解：解散。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫感到失望，内心惭愧，四肢疲乏而不再说话。</p><p>在那个时候，那些见风使舵、奉承上司的人像编成一排似的，嘴巴张开而合不拢，舌头抬起而放不下，神态黯然，如同怀有重担而被斥责一般。</p><p>大夫说：“好吧，胶车突然逢雨，请诸位儒生散了吧。”</p>',120)])])}const y=t(i,[["render",_]]);export{u as __pageData,y as default};
